     1	package components
     2	
     3	import (
     4		"slices"
     5		"strings"
     6		"unicode"
     7	
     8		"github.com/anthnel/devdesk/internal/jobs"
     9		"github.com/anthnel/devdesk/internal/ui/indicator"
    10		"github.com/anthnel/devdesk/internal/ui/theme"
    11	)
    12	
    13	// RowQuery names one row: the registry snapshot, the current context, the
    14	// row's target as the registry knows it, the kinds the view can rerun (nil =
    15	// all), and what the view observes on its own (container, agent).
    16	type RowQuery struct {
    17		Runs     []jobs.Run     // any context; filtered here
    18		Failures []jobs.Failure // any context; filtered here
    19		Context  string
    20		Target   string
    21		Kinds    []jobs.Kind
    22		// Observed is the view's own state (Idle if none); ObservedText is its
    23		// sentence without glyph, shown when Observed wins or on an idle row.
    24		Observed     indicator.State
    25		ObservedText string
    26	}
    27	
    28	// RowActivity is what the first column and the footer say about one row.
    29	type RowActivity struct {
    30		State  indicator.State
    31		Detail RowDetail
    32	}
    33	
    34	// RowState resolves the row's state without building any text. It is what the
    35	// activity column calls; DescribeRow agrees with it by construction.
    36	func RowState(q RowQuery) indicator.State { return resolveRow(q).state }
    37	
    38	// DescribeRow resolves the row and builds its footer sentence.
    39	func DescribeRow(q RowQuery) RowActivity {
    40		f := resolveRow(q)
    41		a := RowActivity{State: f.state}
    42		glyph := indicator.Glyph(f.state, true) // the footer glyph never blinks
    43		switch {
    44		case len(f.active) > 0:
    45			it := f.active[0]
    46			a.Detail = RowDetail{Glyph: glyph, Target: targetDisplay(it.Item.Name())}
    47			if f.state == indicator.Running {
    48				a.Detail.Lead = it.Kind.Verb() + " "
    49			} else {
    50				a.Detail.Lead = "Queued: " + string(it.Kind) + " "
    51			}
    52			a.Detail.Tail = maskedSuffix(f.failures)
    53		case len(f.failures) > 0:
    54			fl := f.failures[0]
    55			a.Detail = RowDetail{Glyph: glyph, Target: targetDisplay(failureName(fl)),
    56				Tail: ": last " + string(fl.Kind) + " failed" + causeSuffix(fl.Kind, fl.Detail) + maskedSuffix(f.failures[1:])}
    57		default:
    58			// No job and no failure: the view's own sentence. Idle shows it with no
    59			// glyph (D8); any other observed state shows it with the glyph.
    60			a.Detail = RowDetail{Lead: oneLine(q.ObservedText)}
    61			if f.state != indicator.Idle && a.Detail.Lead != "" {
    62				a.Detail.Glyph = glyph
    63			}
    64		}
    65		return a
    66	}
    67	
    68	// FailureEvent is the 3-second Error a view posts when an operation fails:
    69	// "Failed to <kind> <target> — <cause>".
    70	func FailureEvent(kind jobs.Kind, target, cause string) string {
    71		return "Failed to " + string(kind) + " " + targetDisplay(target) + causeSuffix(kind, cause)
    72	}
    73	
    74	// rowFacts is the single computation behind RowState and DescribeRow.
    75	type rowFacts struct {
    76		state    indicator.State
    77		active   []jobs.Active  // running first, then queued
    78		failures []jobs.Failure // newest first; the winner when state is Failed
    79	}
    80	
    81	func resolveRow(q RowQuery) rowFacts {
    82		f := rowFacts{
    83			active:   jobs.ActiveOn(q.Runs, q.Context, q.Target, q.Kinds...),
    84			failures: jobs.FailuresOn(q.Failures, q.Context, q.Target, q.Kinds...),
    85		}
    86		slices.SortStableFunc(f.failures, func(a, b jobs.Failure) int { return b.At.Compare(a.At) })
    87		act := indicator.Activity{Failed: len(f.failures) > 0, Observed: q.Observed}
    88		for _, a := range f.active {
    89			act.Running = act.Running || a.Item.State == jobs.ItemRunning
    90			act.Queued = act.Queued || a.Item.State == jobs.ItemQueued
    91		}
    92		f.state = indicator.Resolve(act)
    93		return f
    94	}
    95	
    96	// failureName is the target as the launcher wants it printed.
    97	func failureName(f jobs.Failure) string {
    98		if f.Display != "" {
    99			return f.Display
   100		}
   101		return f.Target
   102	}
   103	
   104	// targetDisplay folds the home directory of an absolute path; an image
   105	// reference or a forge path is kept verbatim.
   106	func targetDisplay(s string) string {
   107		if isPathTarget(s) {
   108			return theme.FoldHome(s)
   109		}
   110		return s
   111	}
   112	
   113	// causeSuffix is " — <cause>", or "" when there is no cause. The cause is put
   114	// on one line and loses a leading "<kind> failed" (the sentence says it) with
   115	// the separator that follows it.
   116	func causeSuffix(kind jobs.Kind, detail string) string {
   117		cause := oneLine(detail)
   118		if p := string(kind) + " failed"; len(cause) >= len(p) && strings.EqualFold(cause[:len(p)], p) {
   119			cause = cause[len(p):]
   120			if cause == "" || cause[0] == ' ' || cause[0] == ':' || cause[0] == '-' || strings.HasPrefix(cause, "—") {
   121				cause = strings.TrimSpace(trimSeparator(strings.TrimSpace(cause)))
   122			} else {
   123				cause = p + cause
   124			}
   125		}
   126		if cause == "" {
   127			return ""
   128		}
   129		return " — " + cause
   130	}
   131	
   132	// trimSeparator removes one leading "—", "--", "-" or ":".
   133	func trimSeparator(s string) string {
   134		for _, sep := range []string{"—", "--", "-", ":"} {
   135			if rest, ok := strings.CutPrefix(s, sep); ok {
   136				return rest
   137			}
   138		}
   139		return s
   140	}
   141	
   142	// oneLine turns control characters into spaces and collapses whitespace runs,
   143	// so free text never spans more than one footer line.
   144	func oneLine(s string) string {
   145		s = strings.Map(func(r rune) rune {
   146			if unicode.IsControl(r) {
   147				return ' '
   148			}
   149			return r
   150		}, s)
   151		return strings.Join(strings.Fields(s), " ")
   152	}
   153	
   154	// maskedSuffix lists the failure kinds a winner hides, in jobs.Kinds() order.
   155	func maskedSuffix(masked []jobs.Failure) string {
   156		var names []string
   157		for _, k := range jobs.Kinds() {
   158			if slices.ContainsFunc(masked, func(f jobs.Failure) bool { return f.Kind == k }) {
   159				names = append(names, string(k))
   160			}
   161		}
   162		switch len(names) {
   163		case 0:
   164			return ""
   165		case 1:
   166			return " · earlier failure: " + names[0] + " (see :jobs)"
   167		}
   168		return " · earlier failures: " + strings.Join(names, ", ") + " (see :jobs)"
   169	}
   170	package jobs
   171	
   172	import "slices"
   173	
   174	// Active is one item of a run that is running or queued on a target.
   175	type Active struct {
   176		Kind  Kind
   177		RunID JobID
   178		Item  Item
   179	}
   180	
   181	// ActiveOn returns the running and queued items on target in contextName:
   182	// running ones first, then queued ones, each group in run order. The target is
   183	// normalized with TargetKey on both sides. With no kinds, every kind is kept.
   184	// Items are copied by value, without their cancel hook. No match returns nil.
   185	func ActiveOn(runs []Run, contextName, target string, kinds ...Kind) []Active {
   186		target = TargetKey(target)
   187		var running, queued []Active
   188		for _, r := range runs {
   189			if r.Context != contextName || (len(kinds) > 0 && !slices.Contains(kinds, r.Kind)) {
   190				continue
   191			}
   192			for _, it := range r.Items {
   193				if TargetKey(it.Target) != target {
   194					continue
   195				}
   196				it.cancel = nil
   197				a := Active{Kind: r.Kind, RunID: r.ID, Item: it}
   198				switch it.State {
   199				case ItemRunning:
   200					running = append(running, a)
   201				case ItemQueued:
   202					queued = append(queued, a)
   203				}
   204			}
   205		}
   206		return append(running, queued...)
   207	}
